<?php
namespace App\Http\Controllers;
use App\Http\Controllers\Concerns\OwnsStartupResources; use App\Models\Startup; use Illuminate\Http\Request;
class StartupController extends Controller { use OwnsStartupResources; private function rules(){return ['name'=>'required|string|max:255','description'=>'nullable|string|max:5000','problem'=>'nullable|string|max:5000','solution'=>'nullable|string|max:5000','target_customers'=>'nullable|string|max:5000','industry'=>'nullable|string|max:255','stage'=>'required|in:idea,validation,MVP,early_growth,growth','current_challenges'=>'nullable|string|max:5000'];} public function store(Request $r){$s=$r->user()->founder()->firstOrCreate([])->startups()->create($r->validate($this->rules()));return response()->json($s,201);} public function show(Request $r,Startup $startup){return $this->owns($r,$startup);} public function update(Request $r,Startup $startup){$this->owns($r,$startup)->update($r->validate($this->rules()));return $startup->fresh();} }
